const content=document.querySelector('#content'),title=document.querySelector('#pageTitle'),modalRoot=document.querySelector('#modalRoot');let activeView='dashboard';
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json','X-Makia-Request':'1'},...opts});let j=null;try{j=await r.json()}catch{}if(!r.ok)throw new Error(j?.detail||'خطا در انجام عملیات');return j}
function fmtBytes(n){if(!n)return'0 B';const u=['B','KB','MB','GB','TB'];const i=Math.min(u.length-1,Math.floor(Math.log(n)/Math.log(1024)));return(n/1024**i).toFixed(i?1:0)+' '+u[i]}
function fmtUp(s){const d=Math.floor(s/86400),h=Math.floor((s%86400)/3600),m=Math.floor((s%3600)/60);return`${d}d ${h}h ${m}m`}
function pct(v){return Math.max(0,Math.min(100,Number(v)||0))}
function svgHistory(rows){if(!rows||rows.length<2)return'<div class="empty">برای نمودار ۲۴ ساعته هنوز داده کافی جمع نشده است.</div>';const w=900,h=220,p=18;const xs=rows.map((_,i)=>p+i*(w-2*p)/(rows.length-1));const path=(key,max=100)=>rows.map((r,i)=>(i?'L':'M')+xs[i].toFixed(1)+' '+(h-p-(Math.max(0,Math.min(max,Number(r[key])||0))/max)*(h-2*p)).toFixed(1)).join(' ');return `<svg class="history-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="cpuG" x1="0" x2="1"><stop offset="0" stop-color="#35d6ff"/><stop offset="1" stop-color="#6c7cff"/></linearGradient><linearGradient id="memG" x1="0" x2="1"><stop offset="0" stop-color="#2dd4a7"/><stop offset="1" stop-color="#a855f7"/></linearGradient></defs><path d="${path('cpu')}" fill="none" stroke="url(#cpuG)" stroke-width="3"/><path d="${path('memory')}" fill="none" stroke="url(#memG)" stroke-width="3" opacity=".9"/></svg><div class="chart-legend"><span><i class="legend-dot cpu"></i>CPU</span><span><i class="legend-dot mem"></i>Memory</span><span>${rows.length} samples</span></div>`}

function healthScore(d){const m=d.metrics,s=d.services.filter(x=>x.active).length/Math.max(1,d.services.length)*100;return Math.round((100-pct(m.cpu))*.2+(100-pct(m.memory))*.25+(100-pct(m.disk))*.25+s*.3)}
function kpi(label,value,p,cls='',sub=''){return`<div class="kpi ${cls}"><div class="label"><span>${label}</span><span>${sub}</span></div><div class="value">${value}</div><div class="bar"><i style="width:${pct(p)}%"></i></div></div>`}
async function setPass(id,type){const el=document.getElementById(id);if(!el)return;const mode=type===4?'pin4':type===6?'pin6':type==='easy8'?'easy8':'strong';try{const r=await api('/api/accounts/generate-secret?mode='+mode);el.value=r.secret;el.type='text';el.focus()}catch(e){alert(e.message)}}
function setExpiryDays(id,days){const el=document.getElementById(id);if(!el)return;const d=new Date();d.setDate(d.getDate()+Number(days));el.value=d.toISOString().slice(0,10)}
function quotaLabel(mb){if(!mb)return'بدون سقف';return mb>=1024?(mb/1024).toFixed(mb%1024?1:0)+' GB':mb+' MB'}
function statusFor(a){if(!a.enabled)return'<span class="status-chip bad">Locked</span>';if(a.expired)return'<span class="status-chip bad">Expired</span>';if(a.days_left!==null&&a.days_left<=7)return'<span class="status-chip warn">'+a.days_left+' روز</span>';return'<span class="status-chip ok">Active</span>'}
async function dashboard(){title.textContent='Overview';content.innerHTML='<div class="empty">در حال دریافت وضعیت سرور…</div>';const [d,hist]=await Promise.all([api('/api/overview'),api('/api/metrics/history?hours=24')]),m=d.metrics,score=healthScore(d);content.innerHTML=`<div class="hero"><div><div class="eyebrow">INFRASTRUCTURE OVERVIEW</div><h2>${m.hostname}</h2><p>نمای لحظه‌ای سلامت سرور، حساب‌ها، نشست‌های فعال و سرویس‌های حیاتی Makia.</p><div class="host-meta"><span class="chip">Kernel ${m.kernel}</span><span class="chip">${m.cpu_cores} CPU Threads</span><span class="chip">Uptime ${fmtUp(m.uptime_seconds)}</span><span class="chip">v${d.version}</span></div></div><div class="health-ring"><div class="ring" style="--pct:${score}%"><div><b>${score}</b><span>HEALTH SCORE</span></div></div></div></div><div class="kpi-grid">${kpi('CPU',m.cpu+'%',m.cpu,'',''+m.cpu_cores+' threads')}${kpi('Memory',m.memory+'%',m.memory,'green',fmtBytes(m.memory_used)+' / '+fmtBytes(m.memory_total))}${kpi('Disk',m.disk+'%',m.disk,'violet',fmtBytes(m.disk_used)+' / '+fmtBytes(m.disk_total))}${kpi('Online Sessions',d.online_sessions,Math.min(100,d.online_sessions*10),'amber',d.online_users+' users')}</div><div class="kpi-grid">${kpi('Accounts',d.users,Math.min(100,d.users*5),'','managed')}${kpi('Expiring ≤ 7d',d.expiring_soon,Math.min(100,d.expiring_soon*20),'amber','attention')}${kpi('Limit Violations',d.limit_violations,Math.min(100,d.limit_violations*25),'violet','online > limit')}${kpi('Network RX',fmtBytes(m.network.recv),30,'green','TX '+fmtBytes(m.network.sent))}</div><div class="panel" style="margin-top:14px"><div class="panel-head"><h3>24h Resource History</h3><span>REAL SAMPLES</span></div>${svgHistory(hist)}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Core Services</h3><span>REAL-TIME STATE</span></div>${d.services.map(s=>`<div class="row"><div><i class="status-dot ${s.active?'ok':'bad'}"></i><b>${s.label}</b><div class="muted">${s.name}</div></div><div class="muted">${s.state}</div><div>${s.active?'Healthy':'Attention'}</div><div></div></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>Quick Actions</h3><span>COMMON TASKS</span></div><div class="quick-grid"><button class="quick-card" onclick="switchView('accounts')"><b>+ Account</b><span>ساخت یا مدیریت کاربر</span></button><button class="quick-card" onclick="switchView('sessions')"><b>Live Sessions</b><span>مشاهده و قطع اتصال</span></button><button class="quick-card" onclick="switchView('backups')"><b>Backup</b><span>بکاپ فوری دیتای Makia</span></button><button class="quick-card" onclick="switchView('security')"><b>Security</b><span>Firewall / Fail2ban status</span></button></div></div></div>`}
let accountCache=[];
function setExpiryPreset(id,days){const el=document.getElementById(id);if(!el)return;if(Number(days)===0){el.value='';return}const base=new Date();base.setHours(12,0,0,0);base.setDate(base.getDate()+Number(days));el.value=base.toISOString().slice(0,10)}
function shiftExpiry(id,days){const el=document.getElementById(id);if(!el)return;const today=new Date();today.setHours(12,0,0,0);let base=today;if(el.value){const current=new Date(el.value+'T12:00:00');if(!Number.isNaN(current.getTime())&&current>today)base=current}base.setDate(base.getDate()+Number(days));el.value=base.toISOString().slice(0,10)}
function stepNumber(id,delta,min=1,max=50){const el=document.getElementById(id);if(!el)return;el.value=Math.max(min,Math.min(max,Number(el.value||min)+delta))}
async function accounts(){
  title.textContent='Account Center';
  content.innerHTML='<div class="empty">در حال بارگذاری حساب‌ها…</div>';
  const [rows,defs]=await Promise.all([api('/api/accounts'),api('/api/accounts/new-defaults')]);
  accountCache=rows;
  content.innerHTML=`
  <div class="account-hero panel">
    <div><div class="eyebrow">SSH ACCESS · REAL POLICY ENFORCEMENT</div><h2>مدیریت حرفه‌ای اکانت SSH</h2><p class="muted">Session Limit و Device/IP Limit دو سیاست جدا هستند و هر دو توسط Policy Enforcer اعمال می‌شوند. حجم برای SSH به‌عنوان محدودیت واقعی نمایش داده نمی‌شود؛ Traffic Quota واقعی در Protocol Clients اعمال می‌شود.</p></div>
    <div class="risk-card"><span>RECOMMENDED</span><b>PIN 6</b><small>PIN 4 اختیاری است؛ برای اینترنت عمومی PIN 6 بهتر است.</small></div>
  </div>
  <div class="panel">
    <div class="panel-head"><h3>ساخت اکانت</h3><span>FAST PROVISIONING</span></div>
    <div class="form-grid">
      <label>نام کاربری<div class="input-action"><input id="cUser" value="${defs.username||''}" placeholder="user001"><button class="soft" type="button" onclick="suggestUsername()">Auto</button></div></label>
      <label>رمز / PIN<div class="input-action"><input id="cPass" type="text" inputmode="text" placeholder="Generate or type"><button class="soft" type="button" onclick="toggleSecret('cPass')">👁</button></div>
        <div class="password-tools"><button class="soft" onclick="setPass('cPass',4)">PIN 4</button><button class="soft recommended" onclick="setPass('cPass',6)">PIN 6</button><button class="soft" onclick="setPass('cPass','easy8')">Easy 8</button><button class="soft" onclick="setPass('cPass','strong')">Strong</button></div>
      </label>
      <label>مدت / تاریخ پایان<input id="cExpire" type="date"><div class="password-tools duration-tools"><button class="soft" onclick="setExpiryPreset('cExpire',1)">1 روز</button><button class="soft" onclick="setExpiryPreset('cExpire',3)">3 روز</button><button class="soft" onclick="setExpiryPreset('cExpire',7)">7 روز</button><button class="soft" onclick="setExpiryPreset('cExpire',15)">15 روز</button><button class="soft recommended" onclick="setExpiryPreset('cExpire',30)">30 روز</button><button class="soft" onclick="setExpiryPreset('cExpire',60)">60 روز</button><button class="soft" onclick="setExpiryPreset('cExpire',90)">90 روز</button><button class="soft" onclick="setExpiryPreset('cExpire',0)">بدون انقضا</button></div></label>
      <label>پلن<input id="cPlan" placeholder="30D / VIP / Trial"></label>
      <label>تعداد اتصال همزمان<div class="number-stepper"><button class="soft" onclick="stepNumber('cLimit',-1)">−</button><input id="cLimit" type="number" min="1" max="50" value="1"><button class="soft" onclick="stepNumber('cLimit',1)">+</button></div><span class="muted">تعداد Sessionهای همزمان همین Username</span></label>
      <label>تعداد دستگاه / IP<div class="number-stepper"><button class="soft" onclick="stepNumber('cDevice',-1)">−</button><input id="cDevice" type="number" min="1" max="50" value="1"><button class="soft" onclick="stepNumber('cDevice',1)">+</button></div><span class="muted">تعداد IP مبدأ همزمان؛ مستقل از Session Limit</span></label>
    </div>
    <div class="form-grid two" style="margin-top:12px"><label>یادداشت داخلی<textarea id="cNote" placeholder="نام مشتری، سفارش، توضیح و..."></textarea></label>
      <div class="provision-preview"><span>POLICY ENGINE</span><b>Expiry + Session + Device/IP</b><small>انقضا باعث Lock حساب و قطع Session می‌شود. IP اضافه و Session اضافه نیز به‌صورت دوره‌ای قطع می‌شوند.</small></div>
    </div>
    <div class="toolbar" style="margin-top:16px"><button class="primary wide-btn" onclick="createAccount()">+ ساخت و نمایش اطلاعات</button><button class="ghost" onclick="clearAccountForm()">پاک کردن فرم</button></div>
  </div>
  <div class="panel">
    <div class="panel-head account-tools"><div><h3>کاربران مدیریت‌شده</h3><span id="accountCount">${rows.length} USERS</span></div>
      <div class="filterbar"><input id="accountSearch" placeholder="جستجو نام کاربری / پلن / یادداشت" oninput="renderAccountRows()"><select id="accountFilter" onchange="renderAccountRows()"><option value="all">همه</option><option value="online">آنلاین</option><option value="active">فعال</option><option value="expiring">≤ 7 روز</option><option value="expired">منقضی</option><option value="locked">قفل</option></select></div>
    </div>
    <div class="toolbar bulkbar"><button class="soft" onclick="toggleAllAccounts()">انتخاب همه</button><button class="ghost" onclick="bulkAccounts('lock')">قفل</button><button class="ghost" onclick="bulkAccounts('unlock')">بازکردن</button><button class="ghost" onclick="bulkExtendPreset(7)">+7 روز</button><button class="ghost" onclick="bulkExtendPreset(30)">+30 روز</button><button class="ghost" onclick="bulkExtendPreset(90)">+90 روز</button><button class="ghost" onclick="bulkExtend()">تمدید سفارشی</button><button class="danger" onclick="bulkAccounts('disconnect')">قطع اتصال</button></div>
    <div id="accountRows" class="table"></div>
  </div>`;
  setExpiryPreset('cExpire',30);
  await setPass('cPass',6);
  renderAccountRows();
}
function toggleSecret(id){const el=document.getElementById(id);if(el)el.type=el.type==='password'?'text':'password'}
async function suggestUsername(){try{const d=await api('/api/accounts/new-defaults');cUser.value=d.username||''}catch(e){alert(e.message)}}
function clearAccountForm(){if(document.getElementById('cUser'))cUser.value='';if(document.getElementById('cPass'))cPass.value='';if(document.getElementById('cPlan'))cPlan.value='';if(document.getElementById('cNote'))cNote.value='';if(document.getElementById('cLimit'))cLimit.value=1;if(document.getElementById('cDevice'))cDevice.value=1;setExpiryPreset('cExpire',30)}
function renderAccountRows(){
  const root=document.getElementById('accountRows');if(!root)return;
  const q=(document.getElementById('accountSearch')?.value||'').trim().toLowerCase();
  const f=document.getElementById('accountFilter')?.value||'all';
  let rows=accountCache.filter(a=>{
    const hay=(a.username+' '+(a.plan||'')+' '+(a.note||'')).toLowerCase();
    if(q&&!hay.includes(q))return false;
    if(f==='online'&&!(a.online>0))return false;
    if(f==='active'&&(!a.enabled||a.expired))return false;
    if(f==='expiring'&&!(a.days_left!==null&&a.days_left>=0&&a.days_left<=7))return false;
    if(f==='expired'&&!a.expired)return false;
    if(f==='locked'&&a.enabled)return false;
    return true;
  });
  document.getElementById('accountCount').textContent=rows.length+' / '+accountCache.length+' USERS';
  root.innerHTML=rows.length?rows.map(a=>`<div class="row account-row"><div><label class="check-user"><input class="account-check" type="checkbox" value="${a.username}"><div><b>${a.username}</b><div class="chips">${statusFor(a)}<span class="status-chip">Sessions ${a.online}/${a.connection_limit}</span><span class="status-chip">Devices ${(a.online_ips||[]).length}/${a.device_limit}</span></div></div></label></div><div><b>${a.plan||'—'}</b><div class="muted">${a.expire_date||'بدون انقضا'} ${a.days_left!==null?'· '+a.days_left+'d':''}</div></div><div><b>${(a.online_ips||[]).length?((a.online_ips||[]).join(', ')):'بدون IP فعال'}</b><div class="muted">${a.note||'بدون یادداشت'}</div></div><div class="toolbar"><button class="ghost" onclick='editAccount(${JSON.stringify(a)})'>ویرایش</button><button class="ghost" onclick="accountAction('${a.username}','disconnect')">قطع</button><button class="danger" onclick="accountAction('${a.username}','delete')">حذف</button></div></div>`).join(''):'<div class="empty">نتیجه‌ای پیدا نشد.</div>';
}
async function bulkExtendPreset(days){const usernames=selectedAccounts();if(!usernames.length){alert('حداقل یک کاربر را انتخاب کنید.');return}try{const r=await api('/api/accounts/bulk',{method:'POST',body:JSON.stringify({usernames,action:'extend',days})});if(r.failed?.length)alert('برخی عملیات ناموفق بود: '+r.failed.length);toast('تمدید انجام شد');await accounts()}catch(e){alert(e.message)}}
async function bulkAccounts(action){const usernames=selectedAccounts();if(!usernames.length){alert('حداقل یک کاربر را انتخاب کنید.');return}if(action==='disconnect'&&!confirm('اتصال کاربران انتخاب‌شده قطع شود؟'))return;try{const r=await api('/api/accounts/bulk',{method:'POST',body:JSON.stringify({usernames,action,days:0})});if(r.failed?.length)alert('برخی عملیات ناموفق بود: '+r.failed.length);await accounts()}catch(e){alert(e.message)}}
async function bulkExtend(){const usernames=selectedAccounts();if(!usernames.length){alert('حداقل یک کاربر را انتخاب کنید.');return}const days=Number(prompt('چند روز به تاریخ فعلی اضافه شود؟','30'));if(!days||days<1)return;try{const r=await api('/api/accounts/bulk',{method:'POST',body:JSON.stringify({usernames,action:'extend',days})});if(r.failed?.length)alert('برخی عملیات ناموفق بود: '+r.failed.length);await accounts()}catch(e){alert(e.message)}}
async function createAccount(){
  const p={username:cUser.value.trim(),password:cPass.value||null,password_mode:'manual',expire_date:cExpire.value||null,plan:cPlan.value,note:cNote.value,connection_limit:Number(cLimit.value||1),device_limit:Number(cDevice.value||1),quota_mb:0,renewal_days:0};
  if(!p.username){alert('نام کاربری را وارد کنید.');return}
  if(!p.password||p.password.length<4){alert('PIN/Password حداقل ۴ کاراکتر باشد.');return}
  try{const r=await api('/api/accounts',{method:'POST',body:JSON.stringify(p)});credentialModal({...p,password:r.password||p.password});accountCache=await api('/api/accounts')}catch(e){alert(e.message)}
}
function editAccount(a){modalRoot.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="eyebrow">SSH ACCOUNT POLICY</div><h3>${a.username}</h3></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="form-grid"><label>رمز جدید / PIN<input id="ePass" type="text" placeholder="خالی = بدون تغییر"><div class="password-tools"><button class="soft" onclick="setPass('ePass',4)">PIN 4</button><button class="soft recommended" onclick="setPass('ePass',6)">PIN 6</button><button class="soft" onclick="setPass('ePass','easy8')">Easy 8</button><button class="soft" onclick="setPass('ePass','strong')">Strong</button></div></label><label>تاریخ پایان<input id="eExpire" type="date" value="${a.expire_date||''}"><div class="password-tools duration-tools"><button class="soft" onclick="shiftExpiry('eExpire',1)">+1</button><button class="soft" onclick="shiftExpiry('eExpire',3)">+3</button><button class="soft" onclick="shiftExpiry('eExpire',7)">+7</button><button class="soft" onclick="shiftExpiry('eExpire',15)">+15</button><button class="soft recommended" onclick="shiftExpiry('eExpire',30)">+30</button><button class="soft" onclick="shiftExpiry('eExpire',60)">+60</button><button class="soft" onclick="shiftExpiry('eExpire',90)">+90</button><button class="soft" onclick="document.getElementById('eExpire').value=''">بدون انقضا</button></div></label><label>پلن<input id="ePlan" value="${(a.plan||'').replaceAll('"','&quot;')}"></label><label>Session Limit<div class="number-stepper"><button class="soft" onclick="stepNumber('eLimit',-1)">−</button><input id="eLimit" type="number" min="1" max="50" value="${a.connection_limit}"><button class="soft" onclick="stepNumber('eLimit',1)">+</button></div></label><label>Device/IP Limit<div class="number-stepper"><button class="soft" onclick="stepNumber('eDevice',-1)">−</button><input id="eDevice" type="number" min="1" max="50" value="${a.device_limit||1}"><button class="soft" onclick="stepNumber('eDevice',1)">+</button></div></label><label>وضعیت<select id="eEnabled"><option value="1" ${a.enabled?'selected':''}>فعال</option><option value="0" ${!a.enabled?'selected':''}>قفل</option></select></label></div><div class="form-grid two" style="margin-top:12px"><label>یادداشت<textarea id="eNote">${a.note||''}</textarea></label><div class="provision-preview"><span>LIVE DEVICES</span><b>${(a.online_ips||[]).length} / ${a.device_limit||1}</b><small>${(a.online_ips||[]).length?(a.online_ips||[]).join('<br>'):'هیچ IP فعالی نیست'}</small></div></div><div class="toolbar" style="margin-top:18px"><button class="primary" onclick="saveAccount('${a.username}')">ذخیره تغییرات</button><button class="ghost" onclick="accountAction('${a.username}','disconnect')">قطع همه</button><button class="danger" onclick="accountAction('${a.username}','delete')">حذف</button></div></div></div>`}
function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast('کپی شد')).catch(()=>prompt('Copy:',text))}
function credentialModal(p){
  const host=window.PANEL_DOMAIN||location.hostname;
  const msg=`Makia SSH Account\nServer: ${host}\nUsername: ${p.username}\nPassword: ${p.password}\nExpire: ${p.expire_date||'No expiry'}\nSessions: ${p.connection_limit}\nDevices/IPs: ${p.device_limit}\nPlan: ${p.plan||'-'}`;
  modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal credential-modal"><div class="modal-head"><div><div class="eyebrow">READY TO SHARE</div><h3>Account Created ✓</h3></div><button class="close-btn" onclick="closeModal();accounts()">×</button></div><div class="credential-grid"><div><span>Server</span><b>${host}</b></div><div><span>Username</span><b>${p.username}</b></div><div><span>Password / PIN</span><b class="credential-secret">${p.password}</b></div><div><span>Expire</span><b>${p.expire_date||'No expiry'}</b></div><div><span>Sessions</span><b>${p.connection_limit}</b></div><div><span>Devices / IP</span><b>${p.device_limit}</b></div></div><div class="notice">رمز در دیتابیس Makia ذخیره نمی‌شود؛ همین حالا آن را کپی و تحویل کاربر بده.</div><div class="toolbar"><button class="primary" onclick='copyText(${JSON.stringify(msg)})'>Copy Full Account</button><button class="ghost" onclick="copyText('${p.password}')">Copy Password</button><button class="ghost" onclick="closeModal();accounts()">Done</button></div></div></div>`;
}
function closeModal(){modalRoot.innerHTML=''}
async function saveAccount(u){try{const p={password:ePass.value||null,expire_date:eExpire.value||null,clear_expire:!eExpire.value,plan:ePlan.value,note:eNote.value,connection_limit:Number(eLimit.value||1),device_limit:Number(eDevice.value||1),quota_mb:0,renewal_days:0,enabled:eEnabled.value==='1'};await api('/api/accounts/'+encodeURIComponent(u),{method:'PUT',body:JSON.stringify(p)});const secret=p.password;closeModal();if(secret)toast('رمز کاربر تغییر کرد؛ آن را تحویل کاربر بده.');await accounts()}catch(e){alert(e.message)}}
async function accountAction(u,a){if(a==='delete'&&!confirm('حذف کامل '+u+' ؟'))return;try{await api('/api/accounts/'+encodeURIComponent(u)+'/'+a,{method:'POST'});closeModal();await accounts()}catch(e){alert(e.message)}}
function selectedAccounts(){return [...document.querySelectorAll('.account-check:checked')].map(x=>x.value)}
function toggleAllAccounts(){const all=[...document.querySelectorAll('.account-check')],should=all.some(x=>!x.checked);all.forEach(x=>x.checked=should)}
async function sessions(){title.textContent='Live Sessions';const rows=await api('/api/sessions');content.innerHTML=`<div class="panel"><div class="panel-head"><h3>Active Sessions</h3><span>${rows.length} ONLINE</span></div><div class="table">${rows.length?rows.map(s=>`<div class="row"><div><i class="status-dot ok"></i><b>${s.username}</b><div class="muted">${s.tty||'-'}</div></div><div class="muted">${s.remote||'local'}</div><div class="muted">${s.since||'-'}</div><div><button class="danger" onclick="disconnectSession('${s.tty}','${s.username}')">Disconnect</button></div></div>`).join(''):'<div class="empty">نشست فعالی نیست.</div>'}</div></div>`}
async function disconnectSession(tty,user){if(!confirm('قطع اتصال '+user+' ؟'))return;try{await api('/api/sessions/disconnect',{method:'POST',body:JSON.stringify({tty,username:user})});await sessions()}catch(e){alert(e.message)}}
function relativeSeen(v){if(!v)return'Never';const t=Date.parse(v);if(Number.isNaN(t))return v;const s=Math.max(0,Math.floor((Date.now()-t)/1000));if(s<60)return s+'s ago';if(s<3600)return Math.floor(s/60)+'m ago';if(s<86400)return Math.floor(s/3600)+'h ago';return Math.floor(s/86400)+'d ago'}
async function nodes(){title.textContent='Nodes';const rows=await api('/api/nodes');content.innerHTML=`<div class="panel"><div class="panel-head"><h3>Multi-node Control</h3><button class="primary" onclick="createNode()">+ Add Node</button></div><div class="notice">هر Node یک Token مستقل دارد. برای محیط واقعی، آدرس Controller را با HTTPS استفاده کنید.</div><div class="table">${rows.length?rows.map(n=>`<div class="row"><div><b>${n.name}</b><div class="muted">${n.hostname||'Waiting for heartbeat'}</div></div><div><span class="status-chip ${n.last_seen_at?'ok':'warn'}">${relativeSeen(n.last_seen_at)}</span><div class="muted">token …${n.token_last4}</div></div><div><b>${n.cpu??'-'}% / ${n.memory??'-'}%</b><div class="muted">CPU / RAM · Disk ${n.disk??'-'}%</div></div><div class="toolbar"><span class="status-chip">${n.version||'-'}</span><button class="danger" onclick="revokeNode(${n.id})">Revoke</button></div></div>`).join(''):'<div class="empty">هنوز Nodeای ثبت نشده است.</div>'}</div></div>`}
async function createNode(){const name=prompt('نام Node:','node-01');if(!name)return;try{const r=await api('/api/nodes',{method:'POST',body:JSON.stringify({name})});const cmd=`MAKIA_CONTROLLER_URL=${location.origin} MAKIA_NODE_TOKEN=${r.token} bash <(curl -fsSL https://raw.githubusercontent.com/mahanneo/Makia-VPS-Manager/main/scripts/install-node-agent.sh)`;modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>Node token created</h3><button class="close-btn" onclick="closeModal();nodes()">×</button></div><div class="notice">این Token فقط همین یک‌بار نمایش داده می‌شود. فرمان زیر را روی VPS مقصد با root اجرا کنید.</div><div class="quick-card"><b style="word-break:break-all">${r.token}</b><span>Node token</span></div><div class="quick-card" style="margin-top:10px"><b style="word-break:break-all;font-size:11px">${cmd}</b><span>Install command</span></div><div class="toolbar" style="margin-top:14px"><button class="primary" onclick="copyText(${JSON.stringify(cmd)})">Copy command</button><button class="ghost" onclick="closeModal();nodes()">Done</button></div></div></div>`}catch(e){alert(e.message)}}
async function revokeNode(id){if(!confirm('دسترسی این Node لغو شود؟'))return;try{await api('/api/nodes/'+id+'/revoke',{method:'POST'});await nodes()}catch(e){alert(e.message)}}

function protocolState(installed,active){if(!installed)return'<span class="status-chip">Not installed</span>';return active?'<span class="status-chip ok">Running</span>':'<span class="status-chip warn">Installed</span>'}
function protocolTile(icon,name,desc,status,actions=''){return`<article class="protocol-tile"><div class="protocol-icon">${icon}</div><div class="protocol-body"><div class="protocol-title"><h3>${name}</h3>${status}</div><p>${desc}</p><div class="toolbar">${actions}</div></div></article>`}
async function protocols(){
  title.textContent='Protocol Hub';
  content.innerHTML='<div class="empty">در حال بررسی سرویس‌ها و Coreها…</div>';
  const [d,clients]=await Promise.all([api('/api/protocols'),api('/api/protocol-clients')]);
  const x=d.xray,w=d.wireguard,o=d.openvpn,s=d.stunnel,ssh=d.ssh;
  const xActions=x.installed?'<button class="primary" onclick="createXrayInbound()">+ Create Client</button><button class="ghost" onclick="openXrayAdvanced()">Advanced Config</button><button class="ghost" onclick="showXrayInbounds()">Inbounds</button>':'<span class="muted">برای Xray از نصب رسمی Core استفاده کن؛ Makia پس از نصب آن را شناسایی می‌کند.</span>';
  const wActions=!w.installed?'<button class="primary" onclick="installProtocol(\'wireguard\')">Install WireGuard</button>':(!w.config?'<button class="primary" onclick="bootstrapWireGuard()">Bootstrap Server</button>':'<button class="primary" onclick="createWireGuardPeer()">+ Create Peer</button>');
  const oActions=!o.installed?'<button class="primary" onclick="installProtocol(\'openvpn\')">Install OpenVPN</button>':(!o.config?'<button class="primary" onclick="bootstrapOpenVPN()">Bootstrap Server</button>':'<button class="primary" onclick="createOpenVPNClient()">+ Create Client</button>');
  const stActions=!s.installed?'<button class="ghost" onclick="installProtocol(\'stunnel\')">Install Stunnel</button>':'<span class="muted">Managed from Services after configuration.</span>';
  content.innerHTML=`
  <div class="panel protocol-hero">
    <div><div class="eyebrow">UNIFIED ACCESS STACK</div><h2>Protocol Hub</h2><p class="muted">Makia فقط قابلیت‌هایی را فعال نشان می‌دهد که Backend واقعی دارند. Xray برای VLESS/VMess/Trojan/Shadowsocks، WireGuard و OpenVPN به‌صورت ماژول‌های مستقل مدیریت می‌شوند.</p></div>
    <div class="protocol-count"><b>${d.capabilities.filter(x=>x.available).length}</b><span>capabilities ready</span></div>
  </div>
  <div class="capability-strip">${d.capabilities.map(x=>`<span class="capability ${x.available?'ready':''}">${x.id}<small>${x.engine}</small></span>`).join('')}</div>
  <div class="protocol-grid">
    ${protocolTile('X','Xray Core','VLESS · VMess · Trojan · Shadowsocks · transport/TLS/REALITY via Xray configuration',protocolState(x.installed,x.service_active),xActions)}
    ${protocolTile('W','WireGuard',`${w.interfaces.length} interface · ${w.peers} peers · native kernel/userspace tooling`,protocolState(w.installed,w.service_active),wActions)}
    ${protocolTile('O','OpenVPN',`${o.servers.length} server profiles · generated .ovpn client bundles`,protocolState(o.installed,o.service_active),oActions)}
    ${protocolTile('S','SSH','Linux account access · expiry · connection policy · live sessions',protocolState(ssh.installed,ssh.service_active),'<button class="ghost" onclick="switchView(\'accounts\')">Manage accounts</button>')}
    ${protocolTile('T','Stunnel','TLS wrapper for TCP services',protocolState(s.installed,s.service_active),stActions)}
  </div>
  <div class="panel"><div class="panel-head"><h3>Xray Inbounds</h3><span>${x.inbounds.length} DETECTED</span></div><div class="table">${x.inbounds.length?x.inbounds.map(i=>`<div class="row"><div><b>${i.tag||'untagged'}</b><div class="muted">${i.protocol}</div></div><div class="muted">${i.listen}:${i.port??'-'}</div><div><span class="status-chip">${i.clients} clients</span></div><div></div></div>`).join(''):'<div class="empty">Inbound قابل‌خواندن پیدا نشد.</div>'}</div></div>
  <div class="panel"><div class="panel-head"><div><h3>Protocol Clients</h3><span>REAL TRAFFIC ACCOUNTING</span></div><button class="ghost" onclick="protocols()">Refresh usage</button></div><div class="table protocol-clients-table">${clients.length?clients.map(protocolClientRow).join(''):'<div class="empty">هنوز Protocol Client ساخته نشده است.</div>'}</div></div>`;
  window.__protocolData=d;
  window.__protocolClients=clients;
}
async function installProtocol(component){if(!confirm('Install '+component+' and required packages?'))return;try{await api('/api/protocols/install',{method:'POST',body:JSON.stringify({component})});toast(component+' installed');await protocols()}catch(e){alert(e.message)}}
function showXrayInbounds(){document.querySelector('.protocol-grid')?.nextElementSibling?.scrollIntoView({behavior:'smooth'})}
function createXrayInbound(){modalRoot.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="eyebrow">XRAY CLIENT + INBOUND</div><h3>ساخت دسترسی Xray</h3></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="form-grid"><label>Protocol<select id="xiProtocol" onchange="syncXrayForm()"><option value="vless">VLESS</option><option value="vmess">VMess</option><option value="trojan">Trojan</option><option value="shadowsocks">Shadowsocks</option><option value="hysteria2">Hysteria2</option></select></label><label>Transport<select id="xiTransport" onchange="syncXrayForm()"><option value="tcp">RAW / TCP</option><option value="ws">WebSocket</option><option value="grpc">gRPC</option><option value="httpupgrade">HTTPUpgrade</option><option value="xhttp">XHTTP</option><option value="kcp">mKCP</option></select></label><label>Security<select id="xiSecurity" onchange="syncXrayForm()"><option value="none">None</option><option value="tls">TLS</option><option value="reality">REALITY</option></select></label><label>Port<input id="xiPort" type="number" min="1" max="65535" value="2087"></label><label>Client name<input id="xiName" value="client01"></label><label>Public domain / IP<input id="xiEndpoint" value="${window.PANEL_DOMAIN||location.hostname}"></label><label id="xiPathWrap">Path / Service / Seed<input id="xiPath" value="/makia"></label><label id="xiSniWrap">Domain / SNI<input id="xiSni" value="${window.PANEL_DOMAIN||''}" placeholder="vpn.example.com"></label><label id="xiRealityWrap">REALITY target<input id="xiRealityDest" value="www.cloudflare.com:443" placeholder="www.example.com:443"></label><label>Traffic quota (GB)<input id="xiQuota" type="number" min="0" step="1" value="50"><span class="muted">0 = Unlimited</span></label><label>Expiry days<input id="xiDays" type="number" min="0" max="3650" value="30"><div class="password-tools"><button class="soft" onclick="xiDays.value=7">7D</button><button class="soft recommended" onclick="xiDays.value=30">30D</button><button class="soft" onclick="xiDays.value=60">60D</button><button class="soft" onclick="xiDays.value=90">90D</button><button class="soft" onclick="xiDays.value=0">∞</button></div></label><label>Traffic reset cycle<input id="xiResetDays" type="number" min="0" max="3650" value="30"><div class="password-tools"><button class="soft" onclick="xiResetDays.value=0">Never</button><button class="soft" onclick="xiResetDays.value=7">7D</button><button class="soft recommended" onclick="xiResetDays.value=30">30D</button></div><span class="muted">مثلاً حجم 50GB هر 30 روز صفر شود</span></label><label>IP / Device policy<input id="xiIpLimit" type="number" min="1" max="50" value="1"><span class="muted">ذخیره و نمایش می‌شود؛ enforcement عمومی Xray IP limit در RC بعدی با log integration فعال می‌شود.</span></label></div><div id="xiCompatNote" class="notice"></div><div class="toolbar"><button class="primary" onclick="submitXrayInbound()">Create, Validate & Restart</button><button class="ghost" onclick="closeModal()">Cancel</button></div></div></div>`;syncXrayForm()}
function syncXrayForm(){const p=xiProtocol.value;if(p==='hysteria2'){xiTransport.value='tcp';xiSecurity.value='tls';xiTransport.disabled=true;xiSecurity.disabled=true}else{xiTransport.disabled=false;xiSecurity.disabled=false}const t=p==='hysteria2'?'hysteria':xiTransport.value,s=p==='hysteria2'?'tls':xiSecurity.value;const pathNeeded=['ws','grpc','httpupgrade','xhttp','kcp'].includes(t);xiPathWrap.style.display=pathNeeded?'block':'none';xiSniWrap.style.display=(s==='tls'||s==='reality')?'block':'none';xiRealityWrap.style.display=s==='reality'?'block':'none';let note='';if(p==='hysteria2'){note='Hysteria2 روی QUIC/Hysteria transport و TLS اجرا می‌شود؛ Certificate دامنه باید از قبل در Domain & TLS صادر شده باشد.'}else if(s==='reality'&&p!=='vless'){note='REALITY در Makia فعلاً فقط برای VLESS فعال است.'}else if(s==='reality'&&!['tcp','grpc','xhttp'].includes(t)){note='REALITY با این Transport در Makia مجاز نیست؛ RAW/TCP، gRPC یا XHTTP انتخاب کن.'}else if(p==='shadowsocks'&&s!=='none'){note='Shadowsocks Quick Profile با TLS/REALITY ترکیب نمی‌شود.'}else if(p==='shadowsocks'){note='Traffic quota per-client برای Shadowsocks Quick Profile در این نسخه قابل enforce نیست.'}else if(s==='tls'){note='TLS نیاز به Certificate معتبر همان SNI در Settings → Domain & TLS دارد.'}else if(s==='reality'){note='Makia کلید X25519 و Short ID را سمت سرور تولید می‌کند و Share Link را تحویل می‌دهد.'}else{note='Config قبل از Apply توسط Xray test می‌شود و در شکست، نسخه قبلی Rollback می‌شود.'}xiCompatNote.textContent=note}
async function submitXrayInbound(){const payload={protocol:xiProtocol.value,transport:xiTransport.value,security:xiSecurity.value,port:Number(xiPort.value),name:xiName.value.trim(),endpoint:xiEndpoint.value.trim(),path_value:xiPath.value||'/',server_name:xiSni.value.trim(),reality_dest:xiRealityDest.value.trim(),quota_gb:Number(xiQuota.value||0),expire_days:Number(xiDays.value||0),ip_limit:Number(xiIpLimit.value||1),reset_days:Number(xiResetDays.value||0)};if(!payload.name||!payload.endpoint||!payload.port){alert('فیلدهای اصلی را کامل کنید.');return}try{const r=await api('/api/protocols/xray/quick-inbound',{method:'POST',body:JSON.stringify(payload)});xrayCredentialModal(r)}catch(e){alert(e.message)}}
function xrayCredentialModal(r){modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal credential-modal"><div class="modal-head"><div><div class="eyebrow">XRAY PROFILE READY</div><h3>${r.protocol.toUpperCase()} · ${r.name}</h3></div><button class="close-btn" onclick="closeModal();protocols()">×</button></div><div class="xray-share"><img src="${r.qr}" alt="QR"><div><div class="credential-grid compact"><div><span>Transport</span><b>${r.transport||'-'}</b></div><div><span>Security</span><b>${r.security||'none'}</b></div><div><span>Port</span><b>${r.port}</b></div><div><span>Quota</span><b>${r.quota_bytes?fmtBytes(r.quota_bytes):'Unlimited'}</b></div></div><span style="margin-top:12px">Share link</span><textarea id="xrayShare" readonly></textarea><div class="toolbar"><button class="primary" onclick="copyText(document.getElementById('xrayShare').value)">Copy link</button><button class="ghost" onclick="downloadText('${r.name}-${r.protocol}.txt',document.getElementById('xrayShare').value)">Download</button></div></div></div>${r.reality&&r.reality.public_key?`<div class="notice">REALITY public key: <b>${r.reality.public_key}</b> · Short ID: <b>${r.reality.short_id}</b></div>`:''}<div class="notice">اطلاعات Credential را همین حالا ذخیره کن. Makia لینک اتصال را برای این Client ثبت کرده، ولی Private credential نباید در کانال ناامن منتشر شود.</div></div></div>`;document.getElementById('xrayShare').value=r.share_link}
function protocolClientRow(c){const quota=Number(c.quota_bytes||0),used=Number(c.usage?.total||0),p=quota?Math.min(100,(used/quota)*100):0;const expiry=c.expire_at?new Date(c.expire_at*1000).toLocaleDateString():'∞';const state=!c.enabled?'Disabled':(c.expired?'Expired':'Active');const sub=location.origin+'/sub/'+c.subscription_id;const ipCount=Number(c.online_ip_count||0),ipState=c.ip_violation?'bad':(ipCount?'ok':'');const accounting=c.accounting_supported!==false;return `<div class="protocol-client-row"><div><div class="client-main"><b>${c.name}</b><span class="protocol-pill">${c.protocol.toUpperCase()}</span><span class="status-chip ${c.enabled&&!c.expired?'ok':'bad'}">${state}</span>${c.ip_violation?'<span class="status-chip bad">IP LIMIT</span>':''}</div><div class="muted">${c.inbound_tag}</div></div><div>${accounting?`<b>${fmtBytes(used)} / ${quota?fmtBytes(quota):'Unlimited'}</b><div class="usage-track"><i style="width:${p}%"></i></div><div class="muted">↑ ${fmtBytes(c.usage?.uplink||0)} · ↓ ${fmtBytes(c.usage?.downlink||0)} · Reset ${c.reset_days?c.reset_days+'d':'manual'}</div>`:'<span class="status-chip warn">Accounting unavailable</span><div class="muted">این پروتکل در این نسخه counter مستقل per-client ندارد.</div>'}</div><div><b>${expiry}</b><div class="muted">${c.days_left===null?'No expiry':c.days_left+' days left'}</div><div class="chips"><button class="status-chip ${ipState}" onclick="showClientIPs(${c.id})">IPs ${ipCount}/${c.ip_limit}</button></div></div><div class="toolbar"><button class="ghost" onclick="copyText('${sub}')">Subscription</button><button class="ghost" onclick="editProtocolClient(${c.id})">Policy</button>${accounting?'<button class="soft" onclick="resetProtocolTraffic('+c.id+')">Reset</button>':''}</div></div>`}

function showClientIPs(id){const c=(window.__protocolClients||[]).find(x=>x.id===id);if(!c)return;const rows=c.online?.ips||[];modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">XRAY ONLINE STATS</div><h3>Live IPs · ${c.name}</h3></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="notice">${c.online?.available?'داده از Xray online-stats API خوانده شده است.':'این Xray Core یا Topology هنوز Online-IP API قابل استفاده ارائه نکرده است.'}</div><div class="ip-list">${rows.length?rows.map(x=>`<div><b>${x.ip}</b><span>${x.last_seen?new Date(x.last_seen*1000).toLocaleString():'-'}</span></div>`).join(''):'<div class="empty">IP آنلاین ثبت نشده است.</div>'}</div></div></div>`}

function editProtocolClient(id){const c=(window.__protocolClients||[]).find(x=>x.id===id);if(!c)return;modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>Policy · ${c.name}</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="form-grid"><label>Traffic quota (GB)<input id="pcQuota" type="number" min="0" step="1" value="${c.quota_bytes?(c.quota_bytes/1073741824).toFixed(2):0}"></label><label>Reset expiry from today (days)<input id="pcDays" type="number" min="0" max="3650" value="${c.days_left??0}"><div class="password-tools"><button class="soft" onclick="pcDays.value=7">7</button><button class="soft" onclick="pcDays.value=30">30</button><button class="soft" onclick="pcDays.value=60">60</button><button class="soft" onclick="pcDays.value=90">90</button><button class="soft" onclick="pcDays.value=0">∞</button></div></label><label>IP policy<input id="pcIp" type="number" min="1" max="50" value="${c.ip_limit||1}"></label><label>Traffic reset cycle (days)<input id="pcReset" type="number" min="0" max="3650" value="${c.reset_days||0}"><div class="password-tools"><button class="soft" onclick="pcReset.value=0">Never</button><button class="soft" onclick="pcReset.value=7">7</button><button class="soft recommended" onclick="pcReset.value=30">30</button></div></label></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveProtocolClient(${c.id})">Save policy</button><button class="ghost" onclick="closeModal()">Cancel</button></div></div></div>`}
async function saveProtocolClient(id){try{await api('/api/protocol-clients/'+id,{method:'PUT',body:JSON.stringify({quota_gb:Number(pcQuota.value||0),expire_days:Number(pcDays.value||0),ip_limit:Number(pcIp.value||1),reset_days:Number(pcReset.value||0),enabled:null})});closeModal();toast('Policy updated');await protocols()}catch(e){alert(e.message)}}
async function resetProtocolTraffic(id){if(!confirm('Traffic counter این Client صفر شود؟'))return;try{await api('/api/protocol-clients/'+id+'/reset-traffic',{method:'POST'});toast('Traffic reset');await protocols()}catch(e){alert(e.message)}}
async function openXrayAdvanced(){try{const r=await api('/api/protocols/xray/config');modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal config-modal"><div class="modal-head"><div><div class="eyebrow">ADVANCED XRAY</div><h3>Validated JSON Configuration</h3><div class="muted">${r.path}</div></div><button class="close-btn" onclick="closeModal()">×</button></div><textarea id="xrayAdvancedText" class="config-output" spellcheck="false"></textarea><div class="notice">برای Routing، Outbounds، Fallbacks، TUN، HTTP/SOCKS و تنظیمات پیشرفته. قبل از Apply با خود Xray تست می‌شود، Backup گرفته می‌شود و در Failure رول‌بک انجام می‌شود.</div><div class="toolbar"><button class="ghost" onclick="validateXrayAdvanced()">Validate</button><button class="primary" onclick="applyXrayAdvanced()">Validate & Apply</button><button class="ghost" onclick="downloadText('xray-config.json',xrayAdvancedText.value)">Export JSON</button></div></div></div>`;xrayAdvancedText.value=JSON.stringify(r.config,null,2)}catch(e){alert(e.message)}}
function parseAdvancedXray(){try{return JSON.parse(xrayAdvancedText.value)}catch(e){throw new Error('JSON نامعتبر: '+e.message)}}
async function validateXrayAdvanced(){try{const config=parseAdvancedXray();await api('/api/protocols/xray/config/validate',{method:'POST',body:JSON.stringify({config})});toast('Xray config valid ✓')}catch(e){alert(e.message)}}
async function applyXrayAdvanced(){if(!confirm('Config اعتبارسنجی، Backup و سپس روی Xray اعمال شود؟'))return;try{const config=parseAdvancedXray();const r=await api('/api/protocols/xray/config',{method:'PUT',body:JSON.stringify({config})});toast('Xray config applied');closeModal();await protocols()}catch(e){alert(e.message)}}
async function bootstrapWireGuard(){const port=Number(prompt('WireGuard UDP port','51820'));if(!port)return;const cidr=prompt('Server tunnel CIDR','10.66.66.1/24');if(!cidr)return;try{const r=await api('/api/protocols/wireguard/bootstrap',{method:'POST',body:JSON.stringify({port,cidr})});toast('WireGuard '+r.interface+' started');await protocols()}catch(e){alert(e.message)}}
async function createWireGuardPeer(){const name=prompt('Peer name','client01');if(!name)return;const endpoint=prompt('Public domain or server IP',window.PANEL_DOMAIN||location.hostname);if(!endpoint)return;const dns=prompt('Client DNS','1.1.1.1')||'1.1.1.1';try{const r=await api('/api/protocols/wireguard/peers',{method:'POST',body:JSON.stringify({name,endpoint,dns})});configModal('WireGuard · '+name,r.config,name+'.conf')}catch(e){alert(e.message)}}
async function bootstrapOpenVPN(){const port=Number(prompt('OpenVPN port','1194'));if(!port)return;const proto=(prompt('Protocol: udp or tcp','udp')||'udp').toLowerCase();try{await api('/api/protocols/openvpn/bootstrap',{method:'POST',body:JSON.stringify({port,proto})});toast('OpenVPN server started');await protocols()}catch(e){alert(e.message)}}
async function createOpenVPNClient(){const name=prompt('Client name','client01');if(!name)return;const endpoint=prompt('Public domain or server IP',window.PANEL_DOMAIN||location.hostname);if(!endpoint)return;const port=Number(prompt('OpenVPN port','1194'))||1194;const proto=(prompt('Protocol: udp or tcp','udp')||'udp').toLowerCase();try{const r=await api('/api/protocols/openvpn/clients',{method:'POST',body:JSON.stringify({name,endpoint,port,proto})});configModal('OpenVPN · '+name,r.config,name+'.ovpn')}catch(e){alert(e.message)}}
function configModal(titleText,textData,fileName){const safeTitle=String(titleText).replaceAll('<','&lt;');modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal config-modal"><div class="modal-head"><div><div class="eyebrow">CLIENT CONFIG</div><h3>${safeTitle}</h3></div><button class="close-btn" onclick="closeModal()">×</button></div><textarea id="configOutput" class="config-output" readonly></textarea><div class="toolbar"><button class="primary" onclick="copyText(document.getElementById('configOutput').value)">Copy config</button><button class="ghost" onclick="downloadText(${JSON.stringify(fileName)},document.getElementById('configOutput').value)">Download file</button><button class="ghost" onclick="closeModal()">Done</button></div></div></div>`;document.getElementById('configOutput').value=textData}
function downloadText(name,text){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function services(){title.textContent='Services';const d=await api('/api/overview');content.innerHTML=`<div class="panel"><div class="panel-head"><h3>Service Control</h3><span>ALLOWLISTED ONLY</span></div>${d.services.map(s=>`<div class="row"><div><i class="status-dot ${s.active?'ok':'bad'}"></i><b>${s.label}</b><div class="muted">${s.name}</div></div><div class="muted">${s.state}</div><div>${s.active?'Running':'Stopped'}</div><div class="toolbar"><button class="ghost" onclick="svc('${s.name}','start')">Start</button><button class="primary" onclick="svc('${s.name}','restart')">Restart</button><button class="danger" onclick="svc('${s.name}','stop')">Stop</button></div></div>`).join('')}</div>`}
async function svc(n,a){try{await api('/api/services/'+n+'/'+a,{method:'POST'});await services()}catch(e){alert(e.message)}}
async function security(){title.textContent='Security Center';const [s,two]=await Promise.all([api('/api/security'),api('/api/admin/2fa/status')]);const card=(name,x)=>`<div class="quick-card"><b>${name}</b><span>${x.installed?(x.active?'Active':'Installed / attention'):'Not installed'}</span><div class="chips"><span class="status-chip ${x.active?'ok':'warn'}">${x.active?'Healthy':'Review'}</span></div></div>`;content.innerHTML=`<div class="panel security-hero"><div><div class="eyebrow">DEFENSE LAYER</div><h2>Security posture</h2><p class="muted">PIN کوتاه فقط برای حساب‌های SSH مجاز است؛ حساب مدیر همچنان سیاست قوی‌تری دارد.</p></div><div class="security-score"><b>${[s.ufw.active,s.fail2ban.active,s.ssh.active,two.enabled].filter(Boolean).length}/4</b><span>controls healthy</span></div></div><div class="panel"><div class="panel-head"><h3>Host Protection</h3><span>LIVE STATUS</span></div><div class="quick-grid">${card('UFW Firewall',s.ufw)}${card('Fail2ban',s.fail2ban)}${card('OpenSSH',s.ssh)}<div class="quick-card"><b>Admin 2FA</b><span>${two.enabled?'Authenticator enabled':'Not enabled'}</span><div class="chips"><span class="status-chip ${two.enabled?'ok':'warn'}">${two.enabled?'Protected':'Recommended'}</span></div></div></div><div class="notice">برای استفاده از PIN چهاررقمی روی اینترنت عمومی، Fail2ban را فعال نگه دار و در صورت امکان SSH را به IPهای مورد اعتماد محدود کن.</div><div class="toolbar"><button class="primary" onclick="switchView('settings')">${two.enabled?'Manage 2FA':'Enable 2FA'}</button></div></div>`}
async function backups(){title.textContent='Backups';const rows=await api('/api/backups');content.innerHTML=`<div class="panel"><div class="panel-head"><h3>Backup Center</h3><button class="primary" onclick="makeBackup()">Create Backup</button></div><div class="table">${rows.length?rows.map(b=>`<div class="row"><div><b>${b.name}</b></div><div class="muted">${fmtBytes(b.size)}</div><div class="muted">${new Date(b.created_at*1000).toLocaleString()}</div><div><span class="status-chip ok">Protected</span></div></div>`).join(''):'<div class="empty">هنوز بکاپی ساخته نشده.</div>'}</div></div>`}
async function makeBackup(){try{await api('/api/backups',{method:'POST'});await backups()}catch(e){alert(e.message)}}
async function auditView(){title.textContent='Audit Logs';const rows=await api('/api/audit');content.innerHTML=`<div class="panel"><div class="panel-head"><h3>Security Audit Trail</h3><span>LAST ${rows.length}</span></div><div class="table">${rows.map(x=>`<div class="row"><div><b>${x.action}</b><div class="muted">${x.actor}</div></div><div class="muted">${x.target||'-'}</div><div class="muted">${new Date(x.created_at).toLocaleString()}</div><div class="muted">${x.ip||'-'}</div></div>`).join('')}</div></div>`}
async function updates(){title.textContent='Update Center';content.innerHTML='<div class="empty">در حال بررسی نسخه…</div>';let s;try{s=await api('/api/update/status')}catch(e){s={current:window.MAKIA_VERSION,latest:null,error:e.message}}const available=s.update_available;content.innerHTML=`<div class="panel update-hero"><div><div class="eyebrow">RELEASE CHANNEL · MAIN</div><h2>${available?'نسخه جدید آماده است':'Makia به‌روز است'}</h2><p class="muted">${s.error?'بررسی آنلاین نسخه ناموفق بود: '+s.error:'نسخه نصب‌شده با VERSION مخزن اصلی مقایسه شد.'}</p></div><div class="version-stack"><span>Installed</span><b>v${s.current||window.MAKIA_VERSION}</b><span>Latest</span><b class="${available?'accent':''}">${s.latest?'v'+s.latest:'Unavailable'}</b></div></div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Safe update workflow</h3><span>CLI VERIFIED PATH</span></div><div class="timeline"><div><b>1</b><span>Pre-update backup</span></div><div><b>2</b><span>Download main</span></div><div><b>3</b><span>Dependencies + service files</span></div><div><b>4</b><span>Restart + health check</span></div></div><div class="command-box">sudo makia-update <button class="soft" onclick="copyText('sudo makia-update')">Copy</button></div></div><div class="panel"><div class="panel-head"><h3>Release status</h3><span>${available?'ACTION AVAILABLE':'NO ACTION'}</span></div><div class="quick-grid"><div class="quick-card"><b>${s.current||'-'}</b><span>Current</span></div><div class="quick-card"><b>${s.latest||'-'}</b><span>Latest on GitHub</span></div></div><div class="notice">آپدیت Web-triggered هنوز عمداً فعال نشده تا rollback اتمیک و امضای Release کامل شود؛ فعلاً CLI مسیر قابل بازیابی‌تری است.</div></div></div>`}
async function settings(){
  title.textContent='Settings';
  const [general,two,tokens]=await Promise.all([api('/api/settings/general'),api('/api/admin/2fa/status'),api('/api/admin/tokens')]);
  window.PANEL_DOMAIN=general.panel_domain||'';
  const ds=general.domain_status||{};
  content.innerHTML=`
  <div class="settings-grid">
    <div class="panel settings-card"><div class="panel-head"><h3>Panel & Language</h3><span>GENERAL</span></div>
      <div class="form-grid"><label>Language<select id="generalLang"><option value="fa" ${general.language==='fa'?'selected':''}>فارسی</option><option value="en" ${general.language==='en'?'selected':''}>English</option></select></label><label>Theme<select id="generalTheme"><option value="midnight" ${general.theme==='midnight'?'selected':''}>Midnight</option><option value="amoled" ${general.theme==='amoled'?'selected':''}>AMOLED</option><option value="graphite" ${general.theme==='graphite'?'selected':''}>Graphite</option></select></label><label>Density<select id="generalDensity"><option value="comfortable" ${general.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${general.density==='compact'?'selected':''}>Compact</option></select></label><label>Panel Domain<input id="generalDomain" value="${general.panel_domain||''}" placeholder="panel.example.com"></label></div>
      <div class="toolbar" style="margin-top:14px"><button class="primary" onclick="saveGeneral()">Save</button><button class="ghost" onclick="applyDomain()">Apply to Nginx</button></div>
    </div>
    <div class="panel settings-card"><div class="panel-head"><h3>Domain & TLS</h3><span>${ds.certificate?'HTTPS READY':'HTTP / PENDING'}</span></div>
      <div class="domain-state"><div><span>DNS</span><b>${ds.resolved_ipv4?.length?ds.resolved_ipv4.join(', '):'Not resolved'}</b></div><div><span>Certificate</span><b>${ds.certificate?'Installed':'Not installed'}</b></div></div>
      <label class="single-label">Let's Encrypt email<input id="tlsEmail" type="email" placeholder="admin@example.com"></label>
      <div class="toolbar" style="margin-top:14px"><button class="primary" onclick="issueCertificate()">Issue / Renew HTTPS</button></div>
      <div class="muted" style="margin-top:10px">قبل از صدور SSL، رکورد A دامنه باید به IP همین VPS اشاره کند.</div>
    </div>
  </div>
  <div class="panel"><div class="panel-head"><h3>Administrator Security</h3><span>MAKIA ${window.MAKIA_VERSION}</span></div><div class="form-grid two"><label>رمز فعلی<input id="oldP" type="password"></label><label>رمز جدید<input id="newP" type="password" placeholder="حداقل 12 کاراکتر"></label></div><p><button class="primary" onclick="changePass()">تغییر رمز</button></p></div>
  <div class="panel"><div class="panel-head"><h3>Two-Factor Authentication</h3><span>${two.enabled?'ENABLED':'OPTIONAL'}</span></div><div class="quick-grid"><div class="quick-card"><b>${two.enabled?'2FA Active':'2FA Disabled'}</b><span>Authenticator TOTP</span><div class="chips"><span class="status-chip ${two.enabled?'ok':'warn'}">${two.enabled?'Protected':'Setup recommended'}</span></div></div><div class="quick-card"><b>Admin Login</b><span>Password + 6 digit code</span></div></div><div class="toolbar" style="margin-top:16px">${two.enabled?'<button class="danger" onclick="disable2FA()">Disable 2FA</button>':'<button class="primary" onclick="setup2FA()">Enable 2FA</button>'}</div></div>
  <div class="panel"><div class="panel-head"><h3>Scoped API Tokens</h3><button class="primary" onclick="createApiToken()">+ New Token</button></div><div class="notice">Tokenها فقط یک‌بار نمایش داده می‌شوند و در دیتابیس فقط Hash آن‌ها نگهداری می‌شود. برای API از HTTPS استفاده کنید.</div><div class="table">${tokens.length?tokens.map(t=>`<div class="row"><div><b>${t.name}</b><div class="muted">…${t.token_last4}</div></div><div class="muted">${t.scopes||'-'}</div><div><span class="status-chip ${t.active?'ok':'bad'}">${t.active?'Active':'Revoked'}</span></div><div class="toolbar">${t.active?'<button class="danger" onclick="revokeApiToken('+t.id+')">Revoke</button>':''}</div></div>`).join(''):'<div class="empty">API Tokenای ساخته نشده است.</div>'}</div></div>`;
}
async function saveGeneral(){try{const r=await api('/api/settings/general',{method:'PUT',body:JSON.stringify({language:generalLang.value,panel_domain:generalDomain.value.trim(),theme:generalTheme.value,density:generalDensity.value})});window.PANEL_DOMAIN=r.panel_domain||'';toast('Settings saved');if(r.language!==window.MAKIA_LANG||r.theme!==window.MAKIA_THEME||r.density!==window.MAKIA_DENSITY){setTimeout(()=>location.reload(),450);return}await settings()}catch(e){alert(e.message)}}
async function applyDomain(){const domain=generalDomain.value.trim();if(!domain){alert('دامنه را وارد کنید.');return}if(!confirm('Nginx server_name روی '+domain+' تنظیم شود؟'))return;try{await api('/api/settings/domain/apply',{method:'POST',body:JSON.stringify({domain})});window.PANEL_DOMAIN=domain;toast('Domain applied to Nginx');await settings()}catch(e){alert(e.message)}}
async function issueCertificate(){const domain=generalDomain.value.trim(),email=tlsEmail.value.trim();if(!domain||!email){alert('دامنه و ایمیل لازم است.');return}if(!confirm('برای '+domain+' گواهی Let\'s Encrypt صادر شود؟'))return;try{const r=await api('/api/settings/domain/certificate',{method:'POST',body:JSON.stringify({domain,email})});toast(r.certificate?'HTTPS enabled':'Certificate command completed');setTimeout(()=>location.href='https://'+domain,1000)}catch(e){alert(e.message)}}
async function createApiToken(){const name=prompt('نام Token:','automation');if(!name)return;const accountsRead=confirm('دسترسی خواندن Accounts هم فعال شود؟\nCancel = فقط status:read');const scopes=['status:read'];if(accountsRead)scopes.push('accounts:read');try{const r=await api('/api/admin/tokens',{method:'POST',body:JSON.stringify({name,scopes})});modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>API Token Created</h3><button class="close-btn" onclick="closeModal();settings()">×</button></div><div class="notice">این Token فقط همین یک‌بار نمایش داده می‌شود. آن را در محل امن ذخیره کنید.</div><div class="quick-card"><b style="word-break:break-all">${r.token}</b><span>${r.scopes.join(', ')}</span></div><div class="toolbar" style="margin-top:14px"><button class="primary" onclick="copyText('${r.token}')">Copy token</button><button class="ghost" onclick="closeModal();settings()">Done</button></div></div></div>`}catch(e){alert(e.message)}}
async function revokeApiToken(id){if(!confirm('این API Token لغو شود؟'))return;try{await api('/api/admin/tokens/'+id+'/revoke',{method:'POST'});await settings()}catch(e){alert(e.message)}}
async function setup2FA(){try{const r=await api('/api/admin/2fa/setup',{method:'POST'});modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>Enable 2FA</h3><button class="close-btn" onclick="closeModal()">×</button></div><div style="text-align:center"><img src="${r.qr}" alt="2FA QR" style="width:220px;max-width:80%;background:white;padding:10px;border-radius:16px"></div><div class="notice">QR را با Google Authenticator / Microsoft Authenticator / 1Password اسکن کنید. اگر اسکن نشد، Secret را دستی وارد کنید.</div><div class="quick-card"><b style="word-break:break-all">${r.secret}</b><span>Manual secret</span></div><div class="form-grid two" style="margin-top:12px"><label>کد ۶ رقمی<input id="twoCode" inputmode="numeric" maxlength="6"></label></div><div class="toolbar" style="margin-top:14px"><button class="primary" onclick="enable2FA()">Verify & Enable</button><button class="ghost" onclick="copyText('${r.secret}')">Copy secret</button></div></div></div>`}catch(e){alert(e.message)}}
async function enable2FA(){try{await api('/api/admin/2fa/enable',{method:'POST',body:JSON.stringify({code:twoCode.value})});closeModal();alert('2FA فعال شد.');await settings()}catch(e){alert(e.message)}}
async function disable2FA(){const password=prompt('رمز فعلی مدیر:');if(password===null)return;const code=prompt('کد ۶ رقمی Authenticator:');if(code===null)return;try{await api('/api/admin/2fa/disable',{method:'POST',body:JSON.stringify({password,code})});alert('2FA غیرفعال شد.');await settings()}catch(e){alert(e.message)}}
async function changePass(){try{await api('/api/admin/password',{method:'POST',body:JSON.stringify({current_password:oldP.value,new_password:newP.value})});alert('رمز مدیر تغییر کرد.')}catch(e){alert(e.message)}}
function toast(msg){let t=document.getElementById('makiaToast');if(!t){t=document.createElement('div');t.id='makiaToast';t.className='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
const commandItems=[['Overview','dashboard'],['Accounts','accounts'],['Live Sessions','sessions'],['Protocols','protocols'],['Nodes','nodes'],['Services','services'],['Security','security'],['Backups','backups'],['Audit Logs','audit'],['Update Center','updates'],['Settings / 2FA / API Tokens','settings']];
function openCommandPalette(){modalRoot.innerHTML=`<div class="modal-backdrop command-backdrop" onclick="if(event.target===this)closeModal()"><div class="command-modal"><input id="commandSearch" autofocus placeholder="Search Makia…  (Ctrl+K)" oninput="renderCommands(this.value)"><div id="commandList"></div></div></div>`;setTimeout(()=>{document.getElementById('commandSearch')?.focus();renderCommands('')},0)}
function renderCommands(q=''){const root=document.getElementById('commandList');if(!root)return;const s=q.toLowerCase();root.innerHTML=commandItems.filter(x=>x[0].toLowerCase().includes(s)).map(x=>`<button onclick="closeModal();switchView('${x[1]}')"><span>${x[0]}</span><kbd>↵</kbd></button>`).join('')}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette()}if(e.key==='Escape')closeModal()});
function applyLanguageShell(){const fa={dashboard:'نمای کلی',accounts:'کاربران',sessions:'اتصال‌های زنده',services:'سرویس‌ها',protocols:'پروتکل‌ها',nodes:'نودها',security:'امنیت',backups:'بکاپ‌ها',audit:'گزارش رویدادها',updates:'بروزرسانی',settings:'تنظیمات'};const en={dashboard:'Overview',accounts:'Accounts',sessions:'Live Sessions',services:'Services',protocols:'Protocols',nodes:'Nodes',security:'Security',backups:'Backups',audit:'Audit Logs',updates:'Update Center',settings:'Settings'};const dict=window.MAKIA_LANG==='en'?en:fa;document.documentElement.lang=window.MAKIA_LANG==='en'?'en':'fa';document.documentElement.dir=window.MAKIA_LANG==='en'?'ltr':'rtl';document.querySelectorAll('nav button[data-view]').forEach(b=>{const label=dict[b.dataset.view];if(!label)return;const span=b.querySelector('span');b.textContent='';if(span)b.appendChild(span);b.appendChild(document.createTextNode(' '+label))})}
const views={dashboard,accounts,sessions,services,protocols,nodes,security,backups,audit:auditView,updates,settings};function currentView(){return(views[activeView]||dashboard)()}function switchView(v){activeView=v;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));currentView()}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));applyLanguageShell();dashboard();
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/static/sw.js').catch(()=>{}));}
